  'Sign in to use this application.': 'ఈ అప్లికేషన్‌ను ఉపయోగించడానికి సైన్ ఇన్ చేయండి.',
  'Waiting for this application’s file to sync…': 'ఈ అప్లికేషన్ ఫైల్ సింక్ అయ్యే వరకు వేచి ఉంది…',
