  '{account} is connected': '{account} కనెక్ట్ అయింది',
  'Choose the chats to open now. The rest wait in the sidebar.':
    'ఇప్పుడు తెరవాల్సిన చాట్‌లను ఎంచుకోండి. మిగతావి సైడ్‌బార్‌లో వేచి ఉంటాయి.',
